      (() => {{
        let first = true
        return () => {{
          if (first) {{
            first = false
            return 'I'
          }
          throw Error('FZAAPP')
        }
      })()
    `)
    await user.click(screen.getByTestId('submit-custom-enemy'))
    await user.click(screen.getByTestId('start-button'))

    for (let i = 0; i < 18; i++) {
      await user.click(screen.getByTestId('down'))
    }

    const error = sinon.stub(console, 'error')
    await user.click(screen.getByTestId('down'))
    error.restore()

    assert.equal(screen.getByTestId('error-real').textContent, 'FZAAPP')
    assert.equal(screen.getByTestId('error-interpretation').textContent, 'Caught this exception while trying to generate a new piece using your custom AI. Game halted.')
    game.unmount()
  })

  it('lets you decide not to replay anything', async () => {
    const game = renderGame()

    const prompt = sinon.stub(window, 'prompt')
    prompt.returns(null)
    await user.click(screen.getByTestId('replay-button'))
    assert.deepEqual(prompt.getCalls().map(call => call.args), [
      ['Paste replay string...']
    ])
    prompt.restore()
    game.unmount()
  })

  // The act of initiating a replay causes a timeout to be created which
  // will play one step of the replay. If we use Sinon to wait for that
  // timeout to trigger, then that'll play back one move... but it will
  // still leave various promises unresolved. `handleMove` won't return,
  // which means `handleRedo` won't return, which means the next replay
  // timeout won't be created. This means we can't just wait for any
  // amount of time... we need create another promise which will resolve
  // along with those other unresolved promises...
  const advanceReplaySteps = async (n: number) => {
    for (let i = 0; i < n; i++) {
      const promise = new Promise(resolve => {
        setTimeout(resolve, replayTimeout)
      })

      // ...then `await` THAT
      await promise
    }
  }

  it('lets you replay a too-long replay', async () => {
    const warn = sinon.stub(console, 'warn')

    const game = renderGame()

    // Replay keeps pressing Down after game over
    const prompt = sinon.stub(window, 'prompt')
    prompt.returns('AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA AAAA')
    await user.click(screen.getByTestId('replay-button'))
    assert.deepEqual(prompt.getCalls().map(call => call.args), [
      ['Paste replay string...']
    ])
    prompt.restore()

    // Play beyond the end of the supplied replay.
    await advanceReplaySteps(300)

    assert.deepEqual(warn.getCalls().map(call => call.args), [
      ['Ignoring input replay step because mode is', 'GAME_OVER']
    ])

    game.unmount()
    warn.restore()
  })

  it('lets you undo and stops replaying when a replay is in progress', async () => {
    const game = renderGame()

    // Replay is an incomplete game
    const prompt = sinon.stub(window, 'prompt')
    prompt.returns('AAAA AAAA AAAA')
    await user.click(screen.getByTestId('replay-button'))
    assert.deepEqual(prompt.getCalls().map(call => call.args), [
      ['Paste replay string...']
    ])
    prompt.restore()

    // Play beyond the end of the supplied replay
    await advanceReplaySteps(60)

    await user.keyboard('{Control>}z{/Control}')
    // TODO: assert that `wellStateId` is now decremented?
    game.unmount()
  })

  it('lets you continue playing from the state an incomplete replay left', async () => {
    const game = renderGame()

    // positions of the live piece's cells, as [row, column]
    const liveCells = () => screen
      .queryAllByTestId('well__cell well__cell--live')
      .map(td => [
        Array.prototype.indexOf.call(td.parentElement!.parentElement!.children, td.parentElement),
        Array.prototype.indexOf.call(td.parentElement!.children, td)
      ])

    // A replay which does not end the game
    const prompt = sinon.stub(window, 'prompt')
    prompt.returns('D')
    await user.click(screen.getByTestId('replay-button'))
    assert.deepEqual(prompt.getCalls().map(call => call.args), [
      ['Paste replay string...']
    ])
    prompt.restore()

    // The single replay move finishes without ending the game;
    // control must return to the player
    await advanceReplaySteps(2)

    assert.equal(screen.queryAllByTestId('down').length, 1)

    const afterReplay = liveCells()

    // Undo the replay's move to sample the state it started from
    await user.keyboard('{Control>}z{/Control}')

    // The game must continue from the state the replay left:
    // the replay's 'D' moved the piece exactly one row down
    assert.deepEqual(afterReplay,
      liveCells().map(([row, col]) => [row + 1, col]))

    // Redo puts the replay's final state back
    await user.keyboard('{Control>}y{/Control}')
    assert.deepEqual(liveCells(), afterReplay)

    // and the player can keep playing on to the end of the game
    let presses = 0
    while (
      screen.queryByTestId('replay-out') === null &&
      presses < 150
    ) {
      await user.keyboard('{Down}')
      presses++
    }

    assert.notEqual(screen.queryByTestId('replay-out'), null)

    // The replay of the finished game is the incomplete replay
    // followed by the player's own moves
    assert.deepEqual(
      hatetrisReplayCodec.decode(screen.getByTestId('replay-out').textContent),
      Array(presses + 1).fill('D')
    )

    game.unmount()
  })
})
